const $=id=>document.getElementById(id),node=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!=null)e.textContent=text;return e;};
const familyColors={'alkali metal':'#f1d7ba','alkaline earth metal':'#f4e8be','transition metal':'#dce8df','post-transition metal':'#d8e8ec',metalloid:'#dce6bc',nonmetal:'#cce5ce',halogen:'#eadce6','noble gas':'#e0dcf1',lanthanide:'#e8e1cc',actinide:'#e9d8ce'};
const units={electronegativity:'',ionization:' eV',density:' g/cm³',melting:' K'};
let tab='learn',compare=[],quiz=null,index=0,answered=false,sessionCorrect=0,practice=emptyPractice(),storageBlocked=false;
try{const raw=localStorage.getItem(PRACTICE_KEY);if(raw){const parsed=parsePractice(raw);if(parsed)practice=parsed;else{storageBlocked=true;notify('저장된 학습 기록의 형식을 확인할 수 없습니다. 원본은 유지됩니다.');}}}catch{storageBlocked=true;}
function notify(text){$('status').textContent=text;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('status').textContent='',5000);}
function save(){if(storageBlocked){notify('기록은 이번 화면에서만 유지됩니다. 파일로 저장할 수 있습니다.');return false;}try{localStorage.setItem(PRACTICE_KEY,JSON.stringify(practice));return true;}catch{storageBlocked=true;notify('브라우저 저장 공간을 사용할 수 없습니다. 기록을 파일로 저장하세요.');return false;}}
function link(text,url){const a=node('a',null,text);a.href=url;a.target='_blank';a.rel='noopener noreferrer';return a;}
function switchTab(next){tab=next;for(const panel of document.querySelectorAll('.panel'))panel.hidden=panel.id!==next;for(const b of document.querySelectorAll('[data-tab]')){if(b.dataset.tab===next)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}if(next==='notebook')renderRecord();}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>switchTab(b.dataset.tab)));
$('jump-practice').addEventListener('click',()=>switchTab('practice'));
$('coverage').replaceChildren(...[[118,'원소'],[DATASET.photoCount,'사진 수록 원소'],[DATASET.photoFileCount,'사진'],[DATASET.crystalCount,'결정 자료']].map(([n,text])=>{const e=node('span');e.append(node('strong',null,n),document.createTextNode(text));return e;}));
$('photo-coverage-note').textContent=`표본·도금·현미경 사진 ${DATASET.specimenCount}종 · 방전광 등 관측 자료 ${DATASET.observationCount}종`;
$('featured').addEventListener('click',()=>openElement(29));
// Do not hardcode an image extension: some licensed samples are PNG.
const featured=ELEMENTS[28].photos[0];if(featured)$('feature-image').src=featured.file;
for(const z of [2,8,9,17,18,54]){const e=ELEMENTS[z-1],p=e.photos.at(-1),button=node('button','phase-card'),img=node('img');img.src=p.file;img.alt=p.label;img.loading='lazy';const text=node('span','phase-card-copy');text.append(node('strong',null,`${e.symbol} · ${e.name}`),node('small',null,PHOTO_PHASES[p.phase]));button.append(img,text);button.addEventListener('click',()=>openElement(z,e.photos.length-1));$('phase-collection').append(button);}
for(const [value,label] of Object.entries(FAMILY_LABELS)){const option=node('option',null,label);option.value=value;$('family').append(option);const legend=node('span');const swatch=node('i');swatch.style.background=familyColors[value];legend.append(swatch,document.createTextNode(label));$('legend').append(legend);}
const tiles=new Map();
for(const e of ELEMENTS){const pos=position(e),button=node('button','element');button.style.gridRow=pos.row;button.style.gridColumn=pos.column;button.dataset.z=e.z;button.setAttribute('aria-label',`${e.z} ${e.name} ${e.symbol} · 상세 정보`);button.append(node('span','z',e.z),node('span','symbol',e.symbol),node('span','name',e.name));if(e.photos.length)button.append(node('i',hasSpecimen(e)?'has-photo':'has-photo observation'));button.addEventListener('click',()=>openElement(e.z));tiles.set(e.z,button);$('periodic-table').append(button);}
for(const [row,text] of [[6,'57–71'],[7,'89–103'],[9,'란타넘족'],[10,'악티늄족']]){const label=node('span','group-marker',text);label.style.gridRow=row;$('periodic-table').append(label);}
$('periodic-table').addEventListener('keydown',event=>{const z=Number(event.target.dataset.z);if(!z)return;const current=position(ELEMENTS[z-1]);let target;
  if(event.key==='ArrowRight')target=ELEMENTS.find(e=>e.z===Math.min(118,z+1));if(event.key==='ArrowLeft')target=ELEMENTS.find(e=>e.z===Math.max(1,z-1));
  if(event.key==='ArrowDown'||event.key==='ArrowUp'){const direction=event.key==='ArrowDown'?1:-1;target=ELEMENTS.filter(e=>position(e).column===current.column&&(position(e).row-current.row)*direction>0).sort((a,b)=>Math.abs(position(a).row-current.row)-Math.abs(position(b).row-current.row))[0];}
  if(target){event.preventDefault();tiles.get(target.z).focus();}
});
function renderTable(){const term=$('search').value.trim().toLowerCase(),family=$('family').value,map=$('map').value,photo=$('photo-filter').value;let matches=0;const values=ELEMENTS.map(e=>e[map]).filter(Number.isFinite),max=Math.max(...values,1),min=Math.min(...values,0);
  for(const e of ELEMENTS){const tile=tiles.get(e.z),matched=(!term||`${e.z} ${e.name} ${e.alias} ${e.symbol} ${e.english}`.toLowerCase().includes(term))&&(family==='all'||e.family===family)&&matchesPhoto(e,photo);tile.classList.toggle('filtered',!matched);tile.style.setProperty('--tile',map==='family'?familyColors[e.family]||'#e4e6dd':e[map]==null?'#e9e8e3':`hsl(${160-95*((e[map]-min)/(max-min||1))} 38% ${93-27*((e[map]-min)/(max-min||1))}%)`);tile.title=`${e.name} ${e.symbol} · ${photoCoverageLabel(e)}${map==='family'?'':` · ${e[map]??'자료 없음'}${units[map]}`}`;tile.setAttribute('aria-pressed',compare.includes(e.z));if(matched)matches++;}
  $('match-count').textContent=`${matches} / 118개`;$('map-note').textContent=map==='family'?'숫자는 원자번호입니다. 초록 점은 표본 사진, 주황 점은 방전광 등 관측 자료입니다.':`진한 색일수록 값이 큽니다. 회색은 자료가 없는 항목입니다. ${map==='melting'||map==='density'?'측정 조건과 동소체에 따라 값이 달라집니다.':'PubChem 수록 값 기준입니다.'}`;
}
for(const id of ['search','family','map','photo-filter'])$(id).addEventListener(id==='search'?'input':'change',renderTable);
function factsList(element,compact=false){const dl=node('dl','facts');const rows=[['원자번호',element.z],['위치',`${element.period}주기${element.group?` · ${element.group}족`:` · ${FAMILY_LABELS[element.family]}`}`],['표준 원자량',element.mass??'표준값 없음'],['전기음성도',element.electronegativity??'자료 없음'],['제1 이온화 에너지',element.ionization==null?'자료 없음':`${element.ionization} eV`],['밀도',element.density==null?'자료 없음':`${element.density} g/cm³`],['녹는점',element.melting==null?'자료 없음':`${element.melting} K`],['끓는점',element.boiling==null?'자료 없음':`${element.boiling} K`]];if(!compact)rows.push(['표준 상태',({'Solid':'고체','Gas':'기체','Liquid':'액체','Expected to be a Gas':'기체로 예측'}[element.state]||element.state)],['산화수',element.oxidation||'자료 없음']);for(const [label,value] of rows)dl.append(node('dt',null,label),node('dd',null,value));return dl;}
function cellDiagram(crystal){const ns='http://www.w3.org/2000/svg';const svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 150 160');svg.setAttribute('role','img');svg.setAttribute('aria-label','단위격자 외곽 도식');
  const [al,be,ga]=[crystal.alpha,crystal.beta,crystal.gamma].map(d=>d*Math.PI/180),a=crystal.a,b=crystal.b,c=crystal.c;
  const cx=c*Math.cos(be),cy=c*(Math.cos(al)-Math.cos(be)*Math.cos(ga))/Math.sin(ga),cz=Math.sqrt(Math.max(0,c*c-cx*cx-cy*cy));
  const points=Array.from({length:8},(_,i)=>{const x=(i&1)*a+((i>>1)&1)*b*Math.cos(ga)+((i>>2)&1)*cx,y=((i>>1)&1)*b*Math.sin(ga)+((i>>2)&1)*cy,z=((i>>2)&1)*cz;return [x*.7-y*.55,-z*.8+x*.25+y*.3];});
  const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),scale=110/Math.max(Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys));const project=p=>[20+(p[0]-Math.min(...xs))*scale,20+(p[1]-Math.min(...ys))*scale];
  for(let i=0;i<8;i++)for(const mask of [1,2,4]){const j=i^mask;if(j<i)continue;const p=project(points[i]),q=project(points[j]),line=document.createElementNS(ns,'line');for(const [k,v] of Object.entries({x1:p[0],y1:p[1],x2:q[0],y2:q[1],stroke:'#6b9d7e','stroke-width':1.4}))line.setAttribute(k,v);svg.append(line);}
  for(const p of points){const [x,y]=project(p),circle=document.createElementNS(ns,'circle');for(const [k,v] of Object.entries({cx:x,cy:y,r:3,fill:'#337b5c'}))circle.setAttribute(k,v);svg.append(circle);}return svg;
}
function openElement(z,initialPhoto=0){const e=ELEMENTS[z-1];$('detail-family').textContent=`${FAMILY_LABELS[e.family]||e.family} · 원자번호 ${z}`;const body=$('element-detail');body.replaceChildren();const heading=node('div','detail-heading'),names=node('div');names.append(node('h2',null,e.name),node('small',null,e.english));heading.append(node('span','detail-symbol',e.symbol),names);body.append(heading);
  const grid=node('div','detail-grid'),left=node('div'),right=node('div');
  if(e.photos.length){const gallery=node('div','photo-gallery'),viewer=node('div'),choices=node('div','photo-choices');
    function showPhoto(index){const p=e.photos[index],figure=node('figure','sample-photo'),img=node('img');img.src=p.file;img.alt=p.caption;const caption=node('figcaption'),badges=node('div','photo-badges');badges.append(node('span',null,PHOTO_PHASES[p.phase]),node('span',null,PHOTO_KINDS[p.kind]));caption.append(badges,node('strong','photo-title',p.label),node('p',null,p.caption));const credit=node('span','credit-line',`${p.author} · `);credit.append(link(p.license,p.licenseUrl),document.createTextNode(' · '),link('원본 사진',p.filePage));caption.append(credit);figure.append(img,caption);viewer.replaceChildren(figure);for(const [i,b]of [...choices.children].entries())b.setAttribute('aria-pressed',i===index);}
    if(e.photos.length>1){choices.setAttribute('aria-label',`${e.name} 사진 선택`);e.photos.forEach((p,i)=>{const b=node('button',null,p.label);b.addEventListener('click',()=>showPhoto(i));choices.append(b);});gallery.append(choices);}gallery.append(viewer);left.append(gallery);showPhoto(Math.max(0,Math.min(initialPhoto,e.photos.length-1)));
    if(!hasSpecimen(e))left.append(node('p','photo-context',e.photoReview.note));
  }else{const empty=node('div','unknown-photo');empty.append(node('strong',null,photoCoverageLabel(e)),node('p',null,e.photoReview.note),link('관련 자료 ↗',e.photoReview.reference));left.append(empty);}
  left.append(factsList(e));if(e.mass==null&&e.isotopeMass!=null)left.append(node('p','small',`PubChem 대표 동위원소 질량: ${e.isotopeMass} u · 표준 원자량과 다른 값입니다.`));
  right.append(node('h3',null,'전자배치'),node('div','electron-config',e.configuration));if(e.predicted)right.append(node('p','detail-warning','초중원소의 전자배치와 벌크 물성에는 예측이 포함됩니다. 실제 관측과 구분해 확인하세요.'));
  right.append(node('p','small','중성 원자의 바닥상태 기준. 궤도 표기 순서가 채워지는 순서나 이온화 순서를 항상 뜻하지는 않습니다.'));const learnConfig=node('button','learn-detail-link','전자배치 읽는 법 →');learnConfig.addEventListener('click',()=>{$('element-dialog').close();switchTab('learn');learning.open('filling');});right.append(learnConfig);
  const actions=node('div','detail-actions'),compareButton=node('button',null,compare.includes(z)?'비교에서 빼기':'비교에 추가'),questionButton=node('button','primary','이 원소 복습');compareButton.addEventListener('click',()=>{if(compare.includes(z))compare=compare.filter(x=>x!==z);else if(compare.length<3)compare.push(z);else{notify('비교는 최대 3개까지 가능합니다.');return;}renderCompare();renderTable();compareButton.textContent=compare.includes(z)?'비교에서 빼기':'비교에 추가';});questionButton.addEventListener('click',()=>{$('element-dialog').close();switchTab('practice');startQuiz([z]);});actions.append(compareButton,questionButton);right.append(actions,node('h3',null,'결정 자료'));
  if(!e.crystals.length)right.append(node('p','small','현재 자료에서 검토 가능한 순수 원소 결정 기록을 찾지 못했습니다. 미관측·미수록 여부는 원문을 확인하세요.'));
  for(const c of e.crystals){const card=node('article','crystal-card'),wrap=node('div','crystal-body'),info=node('p');info.append(node('strong',null,`${c.group} · No. ${c.groupNumber}`),node('br'),document.createTextNode(`a ${c.a} · b ${c.b} · c ${c.c} Å`),node('br'),document.createTextNode(`α ${c.alpha}° · β ${c.beta}° · γ ${c.gamma}°`),node('br'),document.createTextNode(`온도: ${c.temperature?`${c.temperature} K`:'기재 없음'} · 압력: ${c.pressure?`${c.pressure} kPa`:'기재 없음'}`));wrap.append(cellDiagram(c),info);card.append(wrap);const details=node('details'),ref=node('p','small',`${c.authors} (${c.year}). ${c.title}${c.method?` · ${c.method}`:''}`);details.append(node('summary',null,`COD ${c.id} · 원문과 측정 조건`),ref,link('COD / CIF ↗',c.url));if(c.doi)details.append(document.createTextNode(' · '),link('원 논문 ↗','https://doi.org/'+c.doi));card.append(details);right.append(card);}
  const refs=node('div','ref-links');refs.append(link('PubChem 상세','https://pubchem.ncbi.nlm.nih.gov/element/'+e.symbol),link('CIAAW 표준 원자량',DATASET.source.weights));right.append(refs);grid.append(left,right);body.append(grid);if(!$('element-dialog').open)$('element-dialog').showModal();$('element-dialog').scrollTop=0;
}
$('close-detail').addEventListener('click',()=>$('element-dialog').close());$('element-dialog').addEventListener('click',event=>{if(event.target===$('element-dialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();}});
function renderCompare(){const area=$('compare');area.replaceChildren();if(!compare.length){area.append(node('div','empty-compare','원소를 눌러 상세 정보를 열고, 비교에 추가하세요.'));return;}for(const z of compare){const e=ELEMENTS[z-1],card=node('article','compare-card'),heading=node('h3',null,`${e.symbol} · ${e.name}`),remove=node('button',null,'제거');remove.setAttribute('aria-label',`${e.name} 비교에서 제거`);remove.addEventListener('click',()=>{compare=compare.filter(x=>x!==z);renderCompare();renderTable();});heading.append(remove);card.append(heading,factsList(e,true),node('div','electron-config',e.configuration));area.append(card);}}
function newSeed(){const bytes=new Uint32Array(1);crypto.getRandomValues(bytes);return bytes[0];}
function startQuiz(review=[]){if(quiz&&index<quiz.length&&!confirm('진행 중인 문제를 끝내고 새로 시작할까요?'))return;const level=Number($('level').value),category=$('category').value;quiz=generateQuiz({seed:newSeed(),level,category,count:Number($('question-count').value),review});if(!quiz.length){quiz=null;notify('이 난이도에는 선택한 범주의 문제가 없습니다. 범주나 난이도를 바꿔주세요.');return;}index=0;sessionCorrect=0;renderQuestion();}
$('start-quiz').addEventListener('click',()=>startQuiz());$('review-quiz').addEventListener('click',()=>{const ids=practice.entries.filter(e=>e.errors>e.reviews).map(e=>e.z);if(!ids.length){notify('복습할 오답 원소가 없습니다.');return;}startQuiz(ids);});
function renderQuestion(){answered=false;const q=quiz[index],area=$('quiz');area.replaceChildren();const top=node('div','quiz-top');top.append(node('span',null,`${index+1} / ${quiz.length} · ${CATEGORIES[q.category]}`),node('span',null,`맞힌 문제 ${sessionCorrect}`));const track=node('div','quiz-track'),bar=node('span');bar.style.width=`${index/quiz.length*100}%`;track.append(bar);area.append(top,track,node('h2','question',q.prompt));const answers=node('div','answers');q.options.forEach((option,i)=>{const button=node('button','answer');button.append(node('b',null,i+1),node('span',null,option));button.addEventListener('click',()=>answer(i));answers.append(button);});area.append(answers);}
function answer(choice){if(!quiz||answered||index>=quiz.length)return;answered=true;const q=quiz[index],correct=choice===q.answer;if(correct)sessionCorrect++;practice=recordAnswer(practice,q,correct);save();const buttons=[...$('quiz').querySelectorAll('.answer')];buttons.forEach((b,i)=>{b.disabled=true;b.classList.toggle('correct',i===q.answer);b.classList.toggle('wrong',i===choice&&!correct);});const explanation=node('div','explanation');explanation.setAttribute('role','status');explanation.append(node('strong',null,correct?'정답입니다.':'다시 확인해보세요.'),node('p',null,q.explanation));const bottom=node('div','quiz-bottom');bottom.append(node('span','small','숫자 1–4로 답 선택 · 풀이 후 Enter로 다음'));const next=node('button','primary',index+1===quiz.length?'결과 보기':'다음 문제 →');next.id='next-question';next.addEventListener('click',()=>{index++;if(index<quiz.length)renderQuestion();else showResult();});bottom.append(next);$('quiz').append(explanation,bottom);next.focus({preventScroll:true});}
function showResult(){const area=$('quiz'),all=quiz;area.replaceChildren(node('p','eyebrow','SESSION COMPLETE'),node('h2',null,'이번 학습 결과'),node('div','result-score',`${sessionCorrect} / ${all.length}`),node('p','small','오답 원소는 학습 기록에서 다시 확인할 수 있습니다.'));const topics=node('div','result-topics');for(const z of [...new Set(all.flatMap(q=>q.elements))].slice(0,12)){const e=ELEMENTS[z-1],button=node('button',null,`${e.symbol} ${e.name}`);button.addEventListener('click',()=>openElement(z));topics.append(button);}const again=node('button','primary','다른 문제 풀기');again.addEventListener('click',()=>{quiz=null;startQuiz();});area.append(topics,again);}
document.addEventListener('keydown',event=>{if(tab!=='practice'||$('element-dialog').open||event.ctrlKey||event.metaKey||event.altKey||/INPUT|SELECT|TEXTAREA/.test(document.activeElement?.tagName))return;if(/^[1-4]$/.test(event.key)&&quiz&&!answered&&index<quiz.length){event.preventDefault();answer(Number(event.key)-1);}if(event.key==='Enter'&&answered&&event.target!==$('next-question')){$('next-question')?.click();}});
function renderRecord(){$('record-stats').replaceChildren(...[[practice.answered,'완료한 문제'],[practice.answered?`${Math.round(practice.correct/practice.answered*100)}%`:'—','누적 정답률'],[practice.entries.filter(e=>e.errors>e.reviews).length,'복습할 원소']].map(([value,label])=>{const s=node('div','stat-card');s.append(node('strong',null,value),node('span',null,label));return s;}));const area=$('review-elements');area.replaceChildren();for(const entry of [...practice.entries].sort((a,b)=>(b.errors-b.reviews)-(a.errors-a.reviews))){const e=ELEMENTS[entry.z-1],b=node('button','review-element');b.append(node('strong',null,e.symbol),node('span',null,e.name),node('small',null,`오답 ${entry.errors} · 복습 정답 ${entry.reviews}`));b.addEventListener('click',()=>openElement(e.z));area.append(b);}if(!practice.entries.length)area.append(node('p','small','아직 학습 기록이 없습니다. 문제를 풀면 이곳에 쌓입니다.'));}
function download(filename,text){const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=node('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
$('export-record').addEventListener('click',()=>download('element-atlas-practice.json',JSON.stringify(practice,null,2)));
$('import-record').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>40000){notify('기록 파일이 너무 큽니다. 최대 40KB입니다.');return;}const parsed=parsePractice(await file.text());if(!parsed){notify('지원하지 않는 기록 파일입니다. 기존 기록은 유지됩니다.');return;}if(!confirm('현재 학습 기록을 불러온 기록으로 바꿀까요?'))return;practice=parsed;storageBlocked=false;const stored=save();renderRecord();notify(stored?'학습 기록을 불러와 저장했습니다.':'이 화면에 불러왔지만 브라우저에 저장하지 못했습니다. 새로고침 전에 파일로 저장하세요.');});
$('reset-record').addEventListener('click',()=>{if(!confirm('이 브라우저의 학습 기록을 초기화할까요? 필요한 기록은 먼저 파일로 저장하세요.'))return;practice=emptyPractice();storageBlocked=false;save();renderRecord();});
$('source-summary').textContent=`수치 자료 ${DATASET.acquired} · 사진 검토 ${DATASET.photoReviewed} · ${DATASET.photoCount}종 / ${DATASET.photoFileCount}장 · 결정 자료 ${DATASET.crystalCount}종`;
$('coverage-summary').textContent=`표본·도금·현미경 ${DATASET.specimenCount}종 · 기타 관측 자료 ${DATASET.observationCount}종 · 사진 미수록 ${118-DATASET.photoCount}종`;
for(const e of ELEMENTS){const row=node('article','coverage-item'),button=node('button',null,`${e.z} · ${e.symbol} ${e.name}`);button.addEventListener('click',()=>openElement(e.z));row.append(button,node('small',null,photoCoverageLabel(e)),node('p',null,e.photoReview.note));$('photo-inventory').append(row);
  for(const p of e.photos){const item=node('article','credit');item.append(node('strong',null,`${e.symbol} · ${e.name} · ${p.label}`),node('p',null,`${PHOTO_PHASES[p.phase]} · ${PHOTO_KINDS[p.kind]}`),node('p',null,p.author),link(p.title,p.filePage),node('br'),link(p.license,p.licenseUrl),node('p',null,`${p.changes} · 원 라이선스 유지`));$('all-credits').append(item);}
}
renderTable();renderCompare();
const learning=mountLearning($('learning'),{onElement:openElement,onPractice(category){switchTab('practice');$('category').value=category;startQuiz();}});
